{% set st = states('sensor.home_dashboard_state') %}{% set c = state_attr('sensor.home_dashboard_state','context_bar') %}
{% if st in ['unknown','unavailable'] or c is none %}**Home Dashboard is not publishing.** Turn on `publish_state` in the app's Configuration and start it.
{% else %}**{{ c.text }}**{% if state_attr('sensor.home_dashboard_state','observe_only') %}  ·  _observe-only_{% endif %}{% endif %}

{% set h = state_attr('sensor.home_dashboard_state','hero') %}
