{% elif h.kind == 'issue' %}## {{ h.title }}
{{ h.reason }}

Suggested: **{{ h.primary.label }}**  ·  or "{{ h.secondary.label }}"{% if h.status == 'auto_failed' %}

⚠ The automatic action failed. Do it manually.{% endif %}
{% else %}## {{ h.title }}
{{ h.reason }}{% endif %}

{% set s = state_attr('sensor.home_dashboard_state','secondary') or [] %}
{% for i in s %}- **{{ i.title }}** - {{ i.reason }}  _({{ i.primary.label }})_
{% else %}_No other issues._
{% endfor %}

